        self.getPolygonDrawControl().then(setLayer);
        //self.getCutDrawControl().then(setLayer);
        self.setMode(self.layer ? _TC__WEBPACK_IMPORTED_MODULE_0__["default"].control.Edit.mode.MODIFY : null);
